    char *endptr;
    int num = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        fprintf(stderr, "Invalid input\n");
        return 1;
    }

    if (num >= 0 && num < size) {
        printf("%d\n", array[num]);
    } else {
        printf("invalid input\n");
    }

    return 0;
}
```
