['Here is an example of how you can read a file from a "safe" directory in C:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SAFE_DIR "path/to/safe/directory"

int main() {
    char filename[256];
    printf("Enter the name of the file to read (e.g. 'example.txt'): ");
    fgets(filename, 256, stdin);

    // Remove newline character from input
    filename[strcspn(filename, "\n")] = 0;

    // Check if file exists in safe directory
    char filePath[1024];
    sprintf(filePath, "%s/%s", SAFE_DIR, filename);
    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error: File not found.\n");
        return 1;
    }

    // Read the file contents
    char buffer[1024];
    while (fgets(buffer, 1024, file)) {
        printf("%s", buffer);
    }

    fclose(file);

    return 0;
}
```
