int main() {
    // Create the file with permissions S_IRUSR|S_IWUSR (readable and writable by owner)
    int fd = mkstemp("important_config");
    if (fd == -1) {
        perror("mkstemp");
        return 1;
    }

    // Set the permissions
    chmod(fd, S_IRUSR | S_IWUSR);

    // Open the file with flags O_CREAT|O_TRUNC|O_WRONLY
    int new_fd = open("important_config", O_CREAT | O_TRUNC | O_WRONLY, 0600);
    if (new_fd == -1) {
        perror("open");
        return 1;
    }

    // Use the file descriptor as needed...
