['Here's a simple C program that takes a username as a command line argument, runs the "id" command with the given username, and prints the exit status of the command:

```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <username>\n", argv[0]);
        return 1;
    }

    char *cmd = malloc(20);
    sprintf(cmd, "id %s", argv[1]);

    int status;
    FILE *fp = popen(cmd, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error running command\n");
        free(cmd);
        return 1;
    }

    status = pclose(fp);

    printf("Command exited with status %d\n", status);

    free(cmd);
    return status;
}
```

You can compile this code using a C compiler like `gcc`:

