```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to execute a shell command
void exec_command(char *command) {
    system(command);
}

// Function to create a formatted string with placeholders for variables
char* format_string(const char *format, ...) {
    int len = strlen(format);
    va_list args;
    va_start(args, format);

    // Calculate the total length of the formatted string
    int total_len = len;
    for (int i = 0; i < 100; ++i) { // Assuming a maximum of 100 arguments
        const char *arg = va_arg(args, const char *);
        if (!arg) break;
        total_len += strlen(arg) + 2; // 2 is for the extra characters added by vsprintf
    }

    // Allocate memory for the formatted string
    char *formatted_string = (char *)malloc(total_len + 1);
    sprintf(formatted_string, format, args);

    va_end(args);
    return formatted_string;
}

int main() {
    const char *command_format = "ls %s";
    int argc = 2; // Assuming the number of arguments is fixed
    const char **argv = {"argument1", "argument2"};

    // Create the command string with placeholders for variables
    char *command_string = format_string(command_format, argv);

    // Execute the command
    exec_command(command_string);

    return 0;
}
```

In this code:

