    if (argc != 2) {
        fprintf(stderr, "Error: exactly one argument required\n");
        return 1;
    }

    if (!argv[1] || !strcmp(argv[1], "")) {
        fprintf(stderr, "Error: invalid string argument\n");
        return 1;
    }

    char *str = argv[1];
    for (char *p = str + strlen(str) - 1; p >= str && isspace(*p); p--) {
        *p = '\0';
    }

    for (char *p = str; *p && isspace((unsigned char)*p); p++) {
        *p = '\0';
    }

    *(str + strlen(str)) = '\0'; // null terminate the string

    printf("Truncated string: %s\n", str);

    return 0;
}
```
Here's a brief explanation of the code:

1. The first `if` statement checks if exactly one argument was provided (i.e., `argc == 2`). If not, an error message is printed to stderr and the program exits with a non-zero status code.
